<?php
namespace App\Http\Controllers\Api;
use App\Models\{Task,Project,TimeSession};
use App\Services\{ApiData,TaskOrder,TaskTimer,RecurringTasks,BoardColumns};
use App\Http\Controllers\{TaskLifecycleController,BoardColumnsController};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
class WorkspaceController {
 private function page(Request $r):int {$d=$r->validate(['page'=>'sometimes|integer|min:1','per_page'=>'sometimes|integer|min:1|max:100']);return $d['per_page']??25;}
 private function task(Request $r,int $id,bool $all=false):Task {$q=$all?Task::withTrashed():Task::query();return $q->where('user_id',$r->user()->id)->findOrFail($id);}
 private function project(Request $r,int $id):Project {return Project::where('user_id',$r->user()->id)->findOrFail($id);}
 private function expected(Request $r,$row):void {$d=$r->validate(['expected_version'=>'required|integer|min:1']);abort_unless((int)$row->version===(int)$d['expected_version'],409,'Запись изменилась. Обновите данные и повторите действие.');}
 private function write(Request $r,callable $fn){return app(RecurringTasks::class)->locked($r->user()->id,$fn);}
 private function canonical($v){if(!is_array($v))return $v;if(!array_is_list($v))ksort($v);return array_map(fn($i)=>$this->canonical($i),$v);}
 private function create(Request $r,callable $fn){$key=$r->header('Idempotency-Key');validator(['request_key'=>$key],['request_key'=>'required|uuid'])->validate();$hash=hash('sha256',$r->path().json_encode($this->canonical($r->all()),JSON_THROW_ON_ERROR));return $this->write($r,function()use($r,$key,$hash,$fn){$old=DB::table('api_requests')->where('user_id',$r->user()->id)->where('request_key',$key)->first();if($old){abort_unless($old->fingerprint===$hash,409,'Ключ запроса уже использован для другого действия.');return ApiData::response(json_decode($old->result,true),$old->status);}$data=$fn();DB::table('api_requests')->insert(['user_id'=>$r->user()->id,'request_key'=>$key,'fingerprint'=>$hash,'result'=>json_encode($data,JSON_THROW_ON_ERROR),'status'=>201,'created_at'=>now(),'updated_at'=>now()]);return ApiData::response($data,201);});}
 public function projects(Request $r){$per=$this->page($r);$d=$r->validate(['state'=>['sometimes',Rule::in(['active','archived','all'])]]);$q=Project::where('user_id',$r->user()->id);$state=$d['state']??'active';if($state==='active')$q->whereNull('archived_at');if($state==='archived')$q->whereNotNull('archived_at');return ApiData::page($q->orderBy('id')->paginate($per),[ApiData::class,'project']);}
 public function showProject(Request $r,int $project){return ApiData::response(ApiData::project($this->project($r,$project)));}
 public function createProject(Request $r){$d=$r->validate(['name'=>'required|string|max:120']);return $this->create($r,fn()=>ApiData::project(Project::create($d+['user_id'=>$r->user()->id])->fresh()));}
 public function updateProject(Request $r,int $project){$d=$r->validate(['name'=>'required|string|max:120']);return $this->write($r,function()use($r,$project,$d){$p=$this->project($r,$project);$this->expected($r,$p);$p->name=$d['name'];$p->save();return ApiData::response(ApiData::project($p->fresh()));});}
 public function projectLife(Request $r,int $project,string $action){return $this->write($r,function()use($r,$project,$action){$this->expected($r,$this->project($r,$project));$c=app(TaskLifecycleController::class);$p=$action==='archive'?$c->archiveProject($r,$project):$c->restoreProject($r,$project);return ApiData::response(ApiData::project($p));});}
 public function tasks(Request $r){$per=$this->page($r);$d=$r->validate(['q'=>'sometimes|string|max:240','project_id'=>'sometimes|integer|min:1','column'=>'sometimes|string|max:40','status'=>['sometimes',Rule::in(['todo','doing','done'])],'state'=>['sometimes',Rule::in(['active','archived','trashed','all'])]]);$state=$d['state']??'active';$q=Task::withTrashed()->where('user_id',$r->user()->id);if($state==='active')$q->whereNull('deleted_at')->activeBoard();elseif($state==='trashed')$q->whereNotNull('deleted_at');elseif($state==='archived')$q->whereNull('deleted_at')->where(fn($s)=>$s->whereNotNull('tasks.archived_at')->orWhereHas('project',fn($p)=>$p->whereNotNull('archived_at')));if(isset($d['project_id'])){$this->project($r,$d['project_id']);$q->where('project_id',$d['project_id']);}if(isset($d['column'])){$c=app(BoardColumns::class)->resolve($r->user()->id,$d['column']);$q->where('board_column',$c->key);}if(isset($d['status']))$q->where('status',$d['status']);if(isset($d['q']))$q->where('title','ilike','%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],$d['q']).'%');return ApiData::page($q->orderBy('sort_order')->orderBy('id')->paginate($per),[ApiData::class,'task']);}
 public function showTask(Request $r,int $task){return ApiData::response(ApiData::task($this->task($r,$task,true)));}
 private function taskRules(Request $r,bool $create=false):array{return ['title'=>($create?'required':'sometimes|required').'|string|max:240','project_id'=>['sometimes','nullable',Rule::exists('projects','id')->where('user_id',$r->user()->id)->whereNull('archived_at')],'description'=>'sometimes|nullable|string|max:20000','status'=>['sometimes',Rule::in(['todo','doing','done'])],'column'=>'sometimes|required|string|max:40','priority'=>['sometimes',Rule::in(['normal','high'])],'due_date'=>'sometimes|nullable|date_format:Y-m-d','planned_date'=>'sometimes|nullable|date_format:Y-m-d','checklist'=>'sometimes|array|max:100','checklist.*'=>'required|array:text,done','checklist.*.text'=>'required|string|max:500','checklist.*.done'=>'required|boolean'];}
 public function createTask(Request $r){$d=$r->validate($this->taskRules($r,true));return $this->create($r,function()use($r,$d){$uid=$r->user()->id;$t=app(TaskOrder::class)->create($uid,['title'=>$d['title'],'project_id'=>$d['project_id']??null]);$fields=$d;unset($fields['title']);if(isset($fields['column'])){$fields['board_column']=$fields['column'];unset($fields['column']);}$t=app(TaskOrder::class)->update($uid,$t->id,$fields);return ApiData::task($t);});}
 public function updateTask(Request $r,int $task){$d=$r->validate($this->taskRules($r));return $this->write($r,function()use($r,$task,$d){$t=$this->task($r,$task);$this->expected($r,$t);abort_unless(Task::whereKey($task)->activeBoard()->exists(),422,'Сначала восстановите задачу/проект.');if(isset($d['column'])){$d['board_column']=$d['column'];unset($d['column']);}return ApiData::response(ApiData::task(app(TaskOrder::class)->update($r->user()->id,$task,$d)));});}
 public function move(Request $r,int $task){$d=$r->validate(['column'=>'required|string|max:40','before_id'=>'nullable|integer|min:1']);return $this->write($r,function()use($r,$task,$d){$t=$this->task($r,$task);$this->expected($r,$t);app(TaskOrder::class)->move($r->user()->id,$task,'todo',isset($d['before_id'])?(int)$d['before_id']:null,$d['column']);return ApiData::response(ApiData::task($t->fresh()));});}
 public function delete(Request $r,int $task){return $this->write($r,function()use($r,$task){$t=$this->task($r,$task);$this->expected($r,$t);app(TaskOrder::class)->delete($r->user()->id,$task);return ApiData::response(['deleted'=>true]);});}
 public function taskLife(Request $r,int $task,string $action){return $this->write($r,function()use($r,$task,$action){$this->expected($r,$this->task($r,$task,$action==='restore'));$c=app(TaskLifecycleController::class);$t=$action==='archive'?$c->archive($r,$task):$c->restore($r,$task);return ApiData::response(ApiData::task($t));});}
 public function columns(Request $r){return ApiData::response(app(BoardColumns::class)->all($r->user()->id)->map(fn($c)=>['key'=>$c->key,'name'=>$c->name,'kind'=>$c->kind,'sort_order'=>$c->sort_order]));}
 public function saveColumns(Request $r){return $this->write($r,fn()=>ApiData::response(app(BoardColumnsController::class)->save($r,app(RecurringTasks::class),app(BoardColumns::class))['columns']->map(fn($c)=>['key'=>$c->key,'name'=>$c->name,'kind'=>$c->kind,'sort_order'=>$c->sort_order])));}
 public function timer(Request $r){return ApiData::response(app(TaskTimer::class)->snapshot($r->user()->id));}
 public function startTimer(Request $r,int $task){$d=$r->validate(['request_key'=>'required|uuid']);return ApiData::response(app(TaskTimer::class)->start($r->user()->id,$task,$d['request_key']));}
 public function stopTimer(Request $r,int $session){$d=$r->validate(['reason'=>['required',Rule::in(['pause','stop'])]]);return ApiData::response(app(TaskTimer::class)->stop($r->user()->id,$session,$d['reason']));}
 public function time(Request $r,int $task){$this->task($r,$task);$per=$this->page($r);$p=TimeSession::where('user_id',$r->user()->id)->where('task_id',$task)->orderByDesc('id')->paginate($per);return ApiData::page($p,fn($s)=>['id'=>$s->id,'task_id'=>$s->task_id,'started_at'=>$s->started_at->toIso8601String(),'ended_at'=>$s->ended_at?->toIso8601String(),'duration_seconds'=>$s->duration_seconds,'end_reason'=>$s->end_reason]);}
}
